 where schema_name = 'platform' and function_name = 'relation_field';

update platform.client_callable_door
   set argument_rules = '{"version": 1, "declared_by": "argsruled_every_relation_argument_names_its_check.sql", "declared_at": "2026-09-21 lane ARGS-RULED, per-door reading of the body", "arguments": {"p_organization_id": {"type": "uuid", "position": 1, "check": "custom.assert_client_may_reach(p_organization_id, \u2026) \u2192 iam.has_org_access, on the first line and before any read; a non-member is refused 42501 ''You are not a member of that organization''", "foreign": {"sqlstate": "42501", "same_as_invented": true}, "verified": "static reading 2026-09-21; the same wall is measured live by scripts/campaign-tests/argsruled_green.sql clause 1", "entity": "organization", "access": "member of the organization"}, "p_association_id": {"type": "uuid", "position": 2, "check": "the edge is resolved only within this organization AND with source_type = ''record''; anything else \u2014 a foreign edge, an invented id, an edge of another kind \u2014 returns the empty history and the read is never reached (ARGS-RULED 2026-09-21, migrations/campaign/argsruled_the_far_end_of_a_relation_is_decided_too.sql). A resolved source record then goes through custom.assert_client_may_open at viewer, so the history of an edge is decided at the reading threshold of the record it comes out of.", "foreign": {"note": "the empty history, byte-identical to an invented id", "not_a_leak": true, "same_as_invented": true}, "verified": "static reading 2026-09-21; the skipped branch it closes was found by reading, not measured live \u2014 see PROGRESS-ARGS-RULED.md", "entity": "agent_surface_binding", "access": "viewer on the source record"}}}'::jsonb
 where schema_name = 'platform' and function_name = 'relation_history';

update platform.client_callable_door
   set argument_rules = '{"version": 1, "declared_by": "argsruled_every_relation_argument_names_its_check.sql", "declared_at": "2026-09-21 lane ARGS-RULED, per-door reading of the body", "arguments": {"p_organization_id": {"type": "uuid", "position": 1, "check": "custom.assert_client_may_reach(p_organization_id, \u2026) \u2192 iam.has_org_access, on the first line and before any read; a non-member is refused 42501 ''You are not a member of that organization''", "foreign": {"sqlstate": "42501", "same_as_invented": true}, "verified": "static reading 2026-09-21; the same wall is measured live by scripts/campaign-tests/argsruled_green.sql clause 1", "entity": "organization", "access": "member of the organization"}, "p_target_id": {"type": "uuid", "position": 3, "check": "BOTH ARMS DECIDE, and each decides before it reads. p_target_type = ''record'': custom.has_visibility(viewer) or platform.relation_withheld_label(). Every other entity token: iam.has_access(p_target_type, <this>, ''viewer'') or the same withheld sentence (ARGS-RULED 2026-09-21). Until that migration the second arm read the title column of whatever table p_target_type named, with no access decision and no organization in the WHERE clause, and handed back another tenant''s name.", "foreign": {"note": "platform.relation_withheld_label() \u2014 a sentence, never the title and never the id", "not_a_leak": true, "same_as_invented": true}, "verified": "live 2026-09-21 as test@test.com from the authenticated seat: red twin scripts/campaign-tests/argsruled_red.sql, green scripts/campaign-tests/argsruled_green.sql", "access": "viewer, asked of the kernel that owns the token"}}}'::jsonb
 where schema_name = 'platform' and function_name = 'relation_label';

