   set argument_rules = '{"version": 1, "declared_by": "argsruled_every_relation_argument_names_its_check.sql", "declared_at": "2026-09-21 lane ARGS-RULED, per-door reading of the body", "arguments": {"p_organization_id": {"type": "uuid", "position": 1, "check": "custom.assert_client_may_reach(p_organization_id, \u2026) \u2192 iam.has_org_access, on the first line and before any read; a non-member is refused 42501 ''You are not a member of that organization''", "foreign": {"sqlstate": "42501", "same_as_invented": true}, "verified": "static reading 2026-09-21; the same wall is measured live by scripts/campaign-tests/argsruled_green.sql clause 1", "entity": "organization", "access": "member of the organization"}, "p_record_id": {"type": "uuid", "position": 2, "check": "custom.assert_client_may_change(p_organization_id, <this>, ''platform.relation_on_delete'', ''editor'', ''record'') \u2192 custom.has_visibility, decided before the record is admitted to exist \u2014 this verb takes the pointer out of other people''s records, so it asks the WRITING threshold on the record whose deletion is being carried out", "foreign": {"sqlstate": "42501", "same_as_invented": true}, "verified": "static reading 2026-09-21", "entity": "custom_record", "access": "editor"}}}'::jsonb
 where schema_name = 'platform' and function_name = 'relation_on_delete';

